/* tokens.css — design tokens: fonts, neutral/vertical/dark theme variables */

/* ============================================================
   Aircove Customer Portal — styles.css
   Design tokens + component styles. Visual source of truth.
   Componentized: each block below maps 1:1 to a component the
   Codex team will implement (see manifest.json / README.md).

   THEMING is fully declarative:
     <html data-theme="hvac|snow|lawn|pool|roofing|pest|health|beauty"
           data-mode="light|dark">
   app.js only flips these two attributes — every color derives
   from the custom properties defined here.
   ============================================================ */
/* ---------- Fonts ---------- */
@font-face { font-family: "ManropeFallback"; src: local("Manrope"); }

/* ---------- Design tokens : NEUTRALS (light default) ---------- */
:root {
  --font: "Manrope", system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  --ink:      #1d1d1f;
  --ink-2:    #56607a;
  --ink-3:    #9aa0ad;
  --surface:  #ffffff;
  --surface-2:#f5f5f7;
  --base:     #eef1f6;

  /* rgb triplets used inside rgba() */
  --glass:    255,255,255;   /* frosted-panel fill  */
  --hair:     0,0,0;         /* hairline / shadow    */

  --glass-border: rgba(255,255,255,.70);
  --glass-blur:   blur(24px) saturate(180%);
  --shadow-card:  0 8px 28px rgba(13,38,76,.10), inset 0 1px 0 rgba(255,255,255,.70);
  --shadow-float: 0 12px 40px rgba(13,38,76,.16), inset 0 1px 0 rgba(255,255,255,.80);

  --radius-pill: 999px;
  --radius-card: 22px;
  --radius-lg:   24px;
  --radius-md:   14px;
  --radius-sm:   11px;

  /* semantic status colors */
  --ok:     #1f8a44;  --ok-bg:     rgba(52,199,89,.16);
  --warn:   #b5670a;  --warn-bg:   rgba(255,159,10,.16);
  --danger: #c0392b;  --danger-bg: rgba(255,59,48,.12);
  --info:   #0e8fc4;  --info-bg:   rgba(14,143,196,.16);

  /* ACCENT : HVAC (default vertical) */
  --accent:    #0a5ae6;
  --accent-2:  #2a7bff;
  --accent-3:  #3a90ff;
  --accent-rgb:10,90,230;
  --bg-1: #cfe0ff;  --bg-2: #d2f4ec;  --bg-3: #e7dcff;

  --app-bg:
    radial-gradient(120% 90%  at 0%   0%,   var(--bg-1) 0%, transparent 50%),
    radial-gradient(110% 90%  at 100% 0%,   var(--bg-2) 0%, transparent 44%),
    radial-gradient(120% 120% at 90%  100%, var(--bg-3) 0%, transparent 50%),
    var(--base);
}

/* ---------- Design tokens : VERTICAL THEMES ---------- */
:root[data-theme="snow"] {
  --accent:#0e8fc4; --accent-2:#27a6dd; --accent-3:#46b6e6; --accent-rgb:14,143,196;
  --bg-1:#cfe9f6; --bg-2:#d4eef4; --bg-3:#dee9f7;
}

:root[data-theme="lawn"] {
  --accent:#2f9e44; --accent-2:#3fb657; --accent-3:#5fce74; --accent-rgb:47,158,68;
  --bg-1:#d8f0d6; --bg-2:#e4f4d8; --bg-3:#ebf3df;
}

:root[data-theme="pool"] {
  --accent:#0d9488; --accent-2:#15b3a4; --accent-3:#34ccbd; --accent-rgb:13,148,136;
  --bg-1:#cfeeea; --bg-2:#d6f1ec; --bg-3:#ddeff2;
}

:root[data-theme="roofing"] {
  --accent:#4f46e5; --accent-2:#6d63f5; --accent-3:#8b82ff; --accent-rgb:79,70,229;
  --bg-1:#dcdaf8; --bg-2:#e6e2fb; --bg-3:#efe6fb;
}

:root[data-theme="pest"] {
  --accent:#7c3aed; --accent-2:#9554f5; --accent-3:#ad74ff; --accent-rgb:124,58,237;
  --bg-1:#e7dcfb; --bg-2:#efe2fb; --bg-3:#f2e1f6;
}

:root[data-theme="health"] {
  --accent:#0b7285; --accent-2:#0f8ba0; --accent-3:#22a5bb; --accent-rgb:11,114,133;
  --bg-1:#cfe8ee; --bg-2:#d9eef0; --bg-3:#e2ecf6;
}

:root[data-theme="beauty"] {
  --accent:#d6336c; --accent-2:#e64980; --accent-3:#f06595; --accent-rgb:214,51,108;
  --bg-1:#fbd9e5; --bg-2:#fde2ec; --bg-3:#f7e3f5;
}

/* ---------- Design tokens : DARK MODE ---------- */
:root[data-mode="dark"] {
  --ink:#eef2f8; --ink-2:#aab6c8; --ink-3:#7f8aa0;
  --surface:#1b2230; --surface-2:#151b29; --base:#0d1320;
  --glass:38,46,64; --hair:255,255,255;
  --glass-border: rgba(255,255,255,.14);
  --shadow-card:  0 8px 28px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.06);
  --shadow-float: 0 12px 40px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.08);
  --app-bg:
    radial-gradient(120% 90%  at 0%   0%,   rgba(var(--accent-rgb),.24) 0%, transparent 48%),
    radial-gradient(110% 90%  at 100% 0%,   rgba(var(--accent-rgb),.14) 0%, transparent 46%),
    radial-gradient(120% 120% at 90%  100%, rgba(var(--accent-rgb),.18) 0%, transparent 52%),
    var(--base);
}

/* base.css — reset, base type, links, keyframes */

/* ============================================================
   Base
   ============================================================ */
* { box-sizing: border-box; }

html, body { margin: 0; }

body {
  font-family: var(--font);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; }

a:hover { color: var(--accent-2); }

button { font-family: inherit; }

@keyframes sheen  { 0%{transform:translateX(-140%)} 55%,100%{transform:translateX(260%)} }

@keyframes ping   { 0%{transform:scale(1);opacity:.6} 70%,100%{transform:scale(2.6);opacity:0} }

@keyframes fadein { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:none} }

@keyframes pop    { from{opacity:0;transform:scale(.95) translateY(10px)} to{opacity:1;transform:none} }

@keyframes shimmer{ 0%{background-position:-360px 0} 100%{background-position:360px 0} }

@keyframes route-in{ from{opacity:0;transform:translateY(12px)} to{opacity:1;transform:none} }

.route-enter{ animation: route-in .34s cubic-bezier(.2,.7,.2,1) both; }

@keyframes wt-pulse{ 0%{box-shadow:0 0 0 0 rgba(255,159,10,.55)} 70%{box-shadow:0 0 0 14px rgba(255,159,10,0)} 100%{box-shadow:0 0 0 0 rgba(255,159,10,0)} }

@keyframes wt-glow{ 0%,100%{box-shadow:0 0 0 0 rgba(255,159,10,0)} 50%{box-shadow:0 0 0 3px rgba(255,159,10,.20)} }

.wt-pulse{ animation: wt-pulse 2s cubic-bezier(.4,0,.6,1) infinite; }

@keyframes drawer-in { from { transform: translateX(100%); } to { transform: none; } }

/* components.css — buttons, badges, tabs, cards, panels, states, toast, drawer, dev harness */

/* ============================================================
   ActionButton  — data-module="action-button"
   ============================================================ */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  border: 0; border-radius: var(--radius-pill); cursor: pointer;
  font-weight: 600; font-size: 13px; padding: 9px 16px;
  white-space: nowrap; transition: transform .08s, filter .15s;
}

.btn:active { transform: translateY(1px); }

.btn[disabled] { opacity: .45; cursor: not-allowed; pointer-events: none; }

.btn--primary {
  background: linear-gradient(180deg, var(--accent-2), var(--accent)); color: #fff;
  box-shadow: 0 4px 12px rgba(var(--accent-rgb), .35), inset 0 1px 0 rgba(255,255,255,.4);
}

.btn--primary:hover { filter: brightness(1.05); }

.btn--ghost {
  background: rgba(var(--glass), .7); border: 1px solid var(--glass-border); color: var(--ink);
}

.btn--danger {
  background: rgba(255,59,48,.08); border: 1px solid rgba(255,59,48,.22); color: var(--danger);
}

.btn--info { background: linear-gradient(180deg, var(--accent-3), var(--accent)); color: #fff; }

.btn--onaccent { background: var(--surface); color: var(--accent); }

.btn--onaccent:hover { filter: brightness(.98); }

.btn--glass-hero { background: rgba(255,255,255,.18); border: 1px solid rgba(255,255,255,.35); color: #fff; }

.btn--glass-hero:hover { background: rgba(255,255,255,.26); }

.btn--block { display: flex; width: 100%; }

.btn--lg { padding: 11px 20px; font-weight: 700; }

/* ============================================================
   PageHeader  — data-module="page-header"
   ============================================================ */
.page-header { display: flex; align-items: flex-end; gap: 14px; margin: 8px 4px 18px; }

.page-header__title { font-weight: 800; font-size: 28px; line-height: 1.18; letter-spacing: -.025em; margin: 0; padding-top: 2px; }

.page-header__sub  { font-size: 14.5px; color: var(--ink-2); margin-top: 3px; }

/* ============================================================
   StatusBadge  — data-module="status-badge"
   ============================================================ */
.status-badge {
  display: inline-flex; align-items: center; gap: 6px;
  border-radius: var(--radius-pill); padding: 5px 12px;
  font-weight: 600; font-size: 12px; white-space: nowrap;
}

.status-badge--ok       { background: var(--ok-bg);     color: var(--ok); }

.status-badge--progress { background: rgba(255,159,10,.20); color: var(--warn); }

.status-badge--scheduled{ background: rgba(120,120,128,.18); color: var(--ink-3); }

.status-badge--warn     { background: var(--warn-bg);   color: var(--warn); }

.status-badge--danger   { background: var(--danger-bg); color: var(--danger); }

.status-badge--info     { background: var(--info-bg);   color: var(--info); }

/* ============================================================
   Tabs / SegmentedControl  — data-module="tabs"
   ============================================================ */
.tabs { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }

.tab {
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill); padding: 6px 13px;
  font-weight: 530; font-size: 12.5px; color: var(--ink-2);
  cursor: pointer; white-space: nowrap; user-select: none;
}

.tab:hover { color: var(--ink); }

.tab--active { background: #1d1d1f; color: #fff; font-weight: 590; border-color: transparent; }

:root[data-mode="dark"] .tab--active { background: #fff; color: #10151f; }

.select-pill {
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill); padding: 6px 10px;
  font-weight: 530; font-size: 12.5px; color: var(--ink-2); cursor: pointer;
}

/* Card shell — data-module="glass-card" */
.card {
  background: rgba(var(--glass), .5);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
}

.card__head { display: flex; align-items: center; gap: 10px; padding: 12px 12px 10px; flex-wrap: wrap; }

.card__title { font-weight: 700; font-size: 16px; }

.card--pad { padding: 18px; }

/* ============================================================
   States : loading / empty / error  — data-module respectively
   ============================================================ */
.skeleton {
  background: linear-gradient(90deg, rgba(var(--hair),.06) 25%, rgba(var(--hair),.12) 37%, rgba(var(--hair),.06) 63%);
  background-size: 720px 100%; animation: shimmer 1.4s ease-in-out infinite; border-radius: 8px;
}

.state-block {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: 10px; padding: 54px 24px; animation: fadein .3s ease;
}

.state-block__glyph {
  width: 60px; height: 60px; border-radius: 18px; display: grid; place-items: center;
  font-size: 26px; background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
}

.state-block__glyph--error { background: var(--danger-bg); }

.state-block__title { font-weight: 700; font-size: 17px; }

.state-block__desc { font-size: 13.5px; color: var(--ink-2); max-width: 340px; }

/* ============================================================
   Toast  — data-module="toast"
   ============================================================ */
.toast {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%);
  z-index: 300; display: flex; align-items: center; gap: 10px;
  background: #10151f; color: #fff; border-radius: var(--radius-pill);
  padding: 12px 20px; font-weight: 600; font-size: 13.5px;
  box-shadow: 0 12px 34px rgba(0,0,0,.28); animation: pop .28s ease;
}

.toast__dot { width: 8px; height: 8px; border-radius: var(--radius-pill); background: #34c759; }

/* ============================================================
   Drawer / Modal  — data-module="drawer" / "modal"
   ============================================================ */
.scrim { position: fixed; inset: 0; z-index: 250; background: rgba(10,16,28,.42); backdrop-filter: blur(3px); animation: fadein .2s ease; }

.drawer {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 260; width: min(440px, 92vw);
  background: var(--surface); box-shadow: -20px 0 60px rgba(0,0,0,.28);
  padding: 22px; overflow-y: auto; animation: drawer-in .28s cubic-bezier(.2,.8,.2,1);
}

.drawer__head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }

.drawer__title { font-weight: 800; font-size: 20px; letter-spacing: -.02em; }

.drawer__close { width: 34px; height: 34px; border-radius: var(--radius-pill); background: var(--surface-2); border: 0; cursor: pointer; font-size: 16px; }

/* ============================================================
   Dev harness  — data-dev-toolbar  (PREVIEW ONLY — Codex strips this)
   ============================================================ */
.dev-toolbar {
  position: fixed; left: 50%; bottom: 12px; transform: translateX(-50%);
  z-index: 400; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: center;
  background: rgba(16,21,31,.9); backdrop-filter: blur(14px); color: #cfd6e4;
  border: 1px solid rgba(255,255,255,.1); border-radius: 14px;
  padding: 8px 10px; font: 500 11.5px var(--font); max-width: 96vw;
}

.dev-toolbar select, .dev-toolbar button {
  background: rgba(255,255,255,.08); color: #eef2f8; border: 1px solid rgba(255,255,255,.12);
  border-radius: 8px; padding: 5px 8px; font: 500 11.5px var(--font); cursor: pointer;
}

.dev-toolbar__group { display: flex; align-items: center; gap: 4px; }

.dev-toolbar__label { color: #79839a; text-transform: uppercase; letter-spacing: .06em; font-size: 9.5px; }

.dev-toolbar button.is-on { background: var(--accent); border-color: transparent; color: #fff; }

/* Viewport simulation frame (preview harness) */
.viewport-host { display: flex; justify-content: center; }

.viewport-frame { width: 100%; transition: max-width .2s ease; }

.viewport-frame[data-vw="390"]  { max-width: 390px; }

.viewport-frame[data-vw="768"]  { max-width: 768px; }

/* Wave 14.1 — wide presets are TRUE-width: an explicit width (not just max-width)
   so a narrower preview pane never clamps the layout; the host scrolls instead. */
.viewport-frame[data-vw="1180"] { width: 1180px; min-width: 1180px; max-width: 1180px; }

.viewport-frame[data-vw="1440"] { width: 1440px; min-width: 1440px; max-width: 1440px; background: var(--base); }

.viewport-host:has(.viewport-frame[data-vw="1180"]), .viewport-host:has(.viewport-frame[data-vw="1440"]) { justify-content: flex-start; overflow-x: auto; }

.viewport-frame:not([data-vw="1440"]):not([data-vw="full"]) {
  margin: 14px auto; box-shadow: 0 20px 60px rgba(13,38,76,.18); border-radius: 20px; overflow: hidden; background: var(--base);
}

/* Panel — frosted section card used across detail */
.panel {
  background: rgba(var(--glass), .55);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: 20px;
  box-shadow: 0 8px 28px rgba(13,38,76,.10); padding: 20px;
}

.panel__title { font-weight: 700; font-size: 15px; }

.chip { background: rgba(var(--glass), .6); border: 1px solid var(--glass-border); border-radius: var(--radius-pill); padding: 6px 12px; font-weight: 590; font-size: 12px; color: var(--ink-2); cursor: pointer; white-space: nowrap; }


/* ============================================================
   Wave 13 — authenticated live-data states
   (account bootstrap gate, conflict / command-failure banners,
   contact form fields, message send lifecycle)
   ============================================================ */
.account-gate { display: grid; place-items: center; min-height: min(72vh, 640px); }

.account-gate__card { width: 100%; max-width: 460px; }

.account-gate__actions { display: flex; flex-direction: column; gap: 10px; margin-top: 18px; }

.account-gate__route {
  display: inline-flex; align-items: center; gap: 2px; margin: 4px 0 6px; white-space: nowrap;
  padding: 7px 13px; border-radius: var(--radius-pill); font-size: 12.5px; color: var(--ink-2);
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
}

.conflict-banner {
  display: flex; flex-wrap: wrap; gap: 12px; align-items: center; padding: 13px 16px; margin: 0 0 16px;
  border-radius: 14px; background: rgba(255, 159, 10, .1); border: 1px solid rgba(255, 159, 10, .38);
  animation: fadein .3s ease;
}

.conflict-banner__icon {
  width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center; flex: none;
  font-size: 17px; font-weight: 800; color: var(--warn); background: rgba(255, 159, 10, .16);
}

.conflict-banner__body { flex: 1; min-width: 160px; }

.inline-fail {
  display: flex; gap: 11px; align-items: center; padding: 11px 13px;
  border-radius: 12px; background: var(--danger-bg); border: 1px solid rgba(255, 69, 58, .32);
  animation: fadein .3s ease;
}

.inline-fail__icon {
  width: 22px; height: 22px; border-radius: var(--radius-pill); display: grid; place-items: center; flex: none;
  font-size: 12px; font-weight: 800; color: var(--danger); background: rgba(255, 69, 58, .16);
}

/* contact-details form (profile) */
.field-row { display: flex; flex-direction: column; gap: 6px; }

.field-label { font-size: 12px; font-weight: 700; color: var(--ink-2); letter-spacing: .02em; }

.field {
  width: 100%; padding: 11px 13px; border-radius: 12px; font: inherit; font-size: 14px; color: var(--ink);
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border); outline: none;
}

.field:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .14); }

.field[data-state="invalid"] { border-color: var(--danger); box-shadow: 0 0 0 3px rgba(255, 69, 58, .1); }

.field-error { font-size: 12px; color: var(--danger); }

.contact-form { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }

.vw-mobile .contact-form { grid-template-columns: 1fr; }

/* chat message lifecycle */
.msg-bubble[data-state="sending"] { opacity: .55; }

.msg-bubble[data-state="failed"] { border: 1px solid rgba(255, 69, 58, .45); }

.msg-status { font-size: 11.5px; color: var(--ink-3); margin-top: 3px; text-align: right; }

.msg-status--failed { color: var(--danger); }

.msg-retry { color: var(--accent); font-weight: 700; cursor: pointer; margin-left: 6px; }

/* pending buttons (command in flight — duplicate submission disabled) */
.btn[data-state="pending"] { opacity: .8; }

.btn[data-state="failed"] { box-shadow: 0 0 0 2px rgba(255, 69, 58, .28); }

/* cart row while its mutation command is pending */
.cart-row[data-state="pending"] { opacity: .6; pointer-events: none; }

.cart-row__note { font-size: 12px; color: var(--danger); }


/* ============================================================
   Wave 14 — Calm Harbor spa primitives: unmapped raw status,
   visit-mode chip, read-only chip, code chip, card footnote
   ============================================================ */
/* honest UNMAPPED status: the raw backend code, visually distinct from every
   customer-status badge — never restyled to look reassuring */
.status-badge--unmapped {
  background: transparent; border: 1px dashed rgba(120,120,128,.55); color: var(--ink-2);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10px; letter-spacing: .03em;
}

/* visit mode is explicit text, never color alone */
.visit-mode {
  display: inline-flex; align-items: center; gap: 6px; border-radius: var(--radius-pill);
  padding: 4px 11px; font-size: 12px; font-weight: 620;
  background: rgba(var(--accent-rgb), .08); border: 1px solid rgba(var(--accent-rgb), .22); color: var(--ink);
  white-space: nowrap;
}

.visit-mode__dot { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); flex-shrink: 0; }

.visit-mode--home .visit-mode__dot { background: transparent; border: 2px solid var(--accent); width: 5px; height: 5px; }

.readonly-chip {
  display: inline-flex; align-items: center; border-radius: var(--radius-pill); padding: 4px 10px;
  font-size: 10.5px; font-weight: 680; letter-spacing: .06em; text-transform: uppercase;
  background: rgba(120,120,128,.14); color: var(--ink-3); margin-left: auto; white-space: nowrap;
}

.code-chip {
  display: inline-block; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 10.5px; background: rgba(120,120,128,.12); border-radius: 6px;
  padding: 1px 6px; margin-left: 8px; color: var(--ink-3); overflow-wrap: anywhere;
}

.card__footnote { padding: 12px 16px 14px; font-size: 12px; color: var(--ink-3); border-top: 1px solid var(--glass-border); line-height: 1.5; }

.cr-page {
  min-height: 100vh;
  background: var(--app-bg);
  background-attachment: fixed;
  color: var(--ink);
  font-family: var(--font);
}

.cr-shell {
  width: 100%;
  max-width: 920px;
  margin: 0 auto;
  padding: clamp(20px, 5vw, 48px) clamp(14px, 4vw, 28px) 72px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.cr-muted { color: var(--ink-3); }

.cr-visually-hidden {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.cr-head { display: flex; flex-direction: column; gap: 6px; margin: 0 2px 4px; }

.cr-head__top { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }

.cr-eyebrow {
  margin: 0; font-size: 11.5px; font-weight: 750; letter-spacing: .08em;
  text-transform: uppercase; color: var(--accent);
}

.cr-title {
  margin: 0; font-size: clamp(24px, 3.6vw, 32px); font-weight: 800;
  letter-spacing: -.025em; line-height: 1.15; text-wrap: balance;
}

.cr-title:focus { outline: none; }

.cr-sub { margin: 2px 0 0; max-width: 62ch; font-size: 14.5px; line-height: 1.55; color: var(--ink-2); }

.cr-meta { display: flex; flex-wrap: wrap; gap: 8px; margin: 10px 0 0; }

.cr-meta__item {
  display: inline-flex; align-items: baseline; gap: 6px; max-width: 100%;
  padding: 6px 12px; border-radius: var(--radius-pill); font-size: 13px;
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
}

.cr-meta__label { color: var(--ink-3); font-weight: 600; }

.cr-meta__value { margin: 0; font-weight: 650; color: var(--ink); overflow-wrap: anywhere; }

.cr-link { margin: 6px 0 0; }

.cr-pdf { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; margin-top: 8px; }
.cr-pdf .btn { flex: none; }
.cr-pdf__note { margin: 0; max-width: 60ch; font-size: 12.5px; line-height: 1.5; color: var(--ink-2); }

.cr-link__row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; }

.cr-validity { margin: 0; font-size: 12.5px; color: var(--ink-3); }

.cr-link__copy { padding: 5px 12px; font-size: 12.5px; }

.cr-link[data-link="copied"] .cr-link__copy::before { content: "✓"; font-weight: 800; color: var(--ok); }

.cr-link__note { margin: 6px 0 0; max-width: 62ch; font-size: 12.5px; line-height: 1.5; color: var(--ink-2); }

.cr-link__note + .cr-link__note { margin-top: 2px; }

.cr-link[data-link="failed"] .cr-link__note { display: flex; align-items: flex-start; gap: 7px; }

.cr-link[data-link="failed"] .cr-link__note::before {
  content: "!"; flex: none; width: 16px; height: 16px; margin-top: 1px; border-radius: var(--radius-pill);
  display: grid; place-items: center; font-size: 10.5px; font-weight: 800; line-height: 1;
  color: var(--warn); background: var(--warn-bg);
}

.cr-panel {
  background: rgba(var(--glass), .55);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: var(--radius-card);
  box-shadow: var(--shadow-card); padding: clamp(18px, 3vw, 24px);
}

.cr-section-title { margin: 0 0 12px; font-size: 15px; font-weight: 750; letter-spacing: -.005em; }

.cr-section-heading { margin: 10px 2px 0; font-size: 18px; font-weight: 800; letter-spacing: -.01em; }

.cr-summary { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; }

.cr-summary__item {
  display: flex; flex-direction: column; gap: 4px; min-width: 0;
  padding: 12px 14px; border-radius: var(--radius-md);
  background: rgba(var(--glass), .55); border: 1px solid var(--glass-border); box-shadow: var(--shadow-card);
}

.cr-summary__label { display: flex; align-items: center; gap: 6px; font-size: 12px; line-height: 1.3; color: var(--ink-3); }

.cr-summary__item:not([data-kind="properties"]) .cr-summary__label::before {
  content: ""; width: 7px; height: 7px; flex: none; border-radius: var(--radius-pill); background: var(--info);
}

.cr-summary__item[data-kind="approved"] .cr-summary__label::before { background: var(--ok); }

.cr-summary__item[data-kind="declined"] .cr-summary__label::before { background: var(--danger); }

.cr-summary__item[data-kind="changes"] .cr-summary__label::before { background: var(--warn); }

.cr-summary__value { font-size: 22px; font-weight: 800; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }

.cr-state {
  display: flex; flex-direction: column; align-items: center; text-align: center; gap: 10px;
  margin-top: clamp(16px, 8vh, 72px); padding: clamp(36px, 7vw, 56px) clamp(20px, 5vw, 40px);
}

.cr-state__glyph {
  width: 56px; height: 56px; border-radius: 18px; display: grid; place-items: center;
  font-size: 24px; font-weight: 800; color: var(--ink-2);
  background: rgba(var(--glass), .7); border: 1px solid var(--glass-border);
}

.cr-state--warn .cr-state__glyph { background: var(--warn-bg); color: var(--warn); border-color: transparent; }

.cr-state--error .cr-state__glyph { background: var(--danger-bg); color: var(--danger); border-color: transparent; }

.cr-state--ok .cr-state__glyph { background: var(--ok); color: var(--surface); border-color: transparent; }

.cr-state--info .cr-state__glyph,
.cr-state--progress .cr-state__glyph { background: rgba(var(--accent-rgb), .12); color: var(--accent); border-color: transparent; }

.cr-state__title { margin: 4px 0 0; font-size: 19px; font-weight: 800; letter-spacing: -.01em; line-height: 1.3; }

.cr-state__body { margin: 0; max-width: 44ch; font-size: 14px; line-height: 1.55; color: var(--ink-2); }

.cr-state .btn { margin-top: 8px; }

.cr-state[data-checking="active"] .cr-state__glyph::after {
  content: ""; width: 22px; height: 22px; box-sizing: border-box; border-radius: var(--radius-pill);
  border: 2.5px solid rgba(var(--accent-rgb), .22); border-top-color: var(--accent);
  animation: cr-spin .8s linear infinite;
}

.cr-state__aside {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  width: 100%; max-width: 50ch; box-sizing: border-box;
  margin-top: 14px; padding-top: 18px; border-top: 1px solid rgba(var(--hair), .08);
}

.cr-state__aside-title { margin: 0; font-size: 15px; font-weight: 750; letter-spacing: -.005em; }

.cr-state__aside-text { margin: 0; font-size: 13.5px; line-height: 1.55; color: var(--ink-2); }

.cr-portal__email { font-weight: 700; color: var(--ink); overflow-wrap: anywhere; }

.cr-notice {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 13px 15px; border-radius: 16px;
  background: rgba(var(--accent-rgb), .06); border: 1px solid rgba(var(--accent-rgb), .16);
}

.cr-notice--warn { background: var(--warn-bg); border-color: transparent; }

.cr-notice--ok { background: var(--ok-bg); border-color: transparent; }

.cr-notice__icon {
  width: 26px; height: 26px; flex: none; border-radius: var(--radius-pill); display: grid; place-items: center;
  font-size: 13px; font-weight: 800; background: var(--surface); color: var(--accent);
}

.cr-notice--warn .cr-notice__icon { color: var(--warn); }

.cr-notice--ok .cr-notice__icon { color: var(--ok); }

.cr-notice__icon--busy::after {
  content: ""; width: 14px; height: 14px; box-sizing: border-box; border-radius: var(--radius-pill);
  border: 2px solid rgba(var(--hair), .12); border-top-color: currentColor;
  animation: cr-spin .8s linear infinite;
}

.cr-notice__body { flex: 1 1 240px; min-width: 0; }

.cr-notice__title { margin: 0; font-size: 14px; font-weight: 700; }

.cr-notice__text { margin: 2px 0 0; font-size: 13px; line-height: 1.5; color: var(--ink-2); }

.cr-notice__title + .cr-notice__text { margin-top: 2px; }

.cr-notice__text + .cr-notice__text { margin-top: 6px; }

.cr-notice .btn { flex: none; }

.cr-properties, .cr-services { display: flex; flex-direction: column; gap: 14px; }

.cr-property {
  overflow: hidden;
  background: rgba(var(--glass), .55);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: var(--radius-card); box-shadow: var(--shadow-card);
}

.cr-page[aria-busy="true"] .cr-property { opacity: .72; transition: opacity .2s ease; }

.cr-property__head { display: flex; align-items: flex-start; gap: 12px; padding: 16px 18px 14px; }

.cr-pin {
  width: 24px; height: 24px; flex: none; margin: 3px 3px 0; display: grid; place-items: center;
  border-radius: 999px 999px 999px 3px; transform: rotate(-45deg);
  background: linear-gradient(160deg, var(--accent-3), var(--accent));
  box-shadow: 0 3px 8px rgba(var(--accent-rgb), .3);
}

.cr-pin::after { content: ""; width: 8px; height: 8px; border-radius: var(--radius-pill); background: var(--surface); }

.cr-property[data-state="approved"] .cr-pin { background: var(--ok); box-shadow: none; }

.cr-property[data-state="declined"] .cr-pin { background: var(--danger); box-shadow: none; }

.cr-property[data-state="changes"] .cr-pin { background: var(--warn); box-shadow: none; }

.cr-property[data-state="unknown"] .cr-pin { background: var(--ink-3); box-shadow: none; }

.cr-property__identity { flex: 1; min-width: 0; }

.cr-property__address { margin: 0; font-size: 16px; font-weight: 750; line-height: 1.35; letter-spacing: -.005em; overflow-wrap: anywhere; }

.cr-property__meta { margin: 3px 0 0; font-size: 12.5px; color: var(--ink-3); }

.cr-property__head .status-badge { flex: none; margin-top: 1px; }

.cr-options { list-style: none; margin: 0; padding: 0; }

.cr-option { border-top: 1px solid var(--glass-border); }

.cr-option__toggle {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 13px 18px;
  border: 0; background: transparent; color: var(--ink); font: inherit; text-align: left; cursor: pointer;
}

.cr-option__toggle:hover { background: rgba(var(--glass), .45); }

.cr-option__toggle:focus-visible { outline: none; box-shadow: inset 0 0 0 2px rgba(var(--accent-rgb), .55); }

.cr-option[data-expanded="true"] > .cr-option__toggle { background: rgba(var(--glass), .35); }

.cr-option__label { flex: 1; min-width: 0; font-size: 14.5px; font-weight: 700; }

.cr-option__toggle .status-badge { flex: none; }

.cr-pick-group { min-width: 0; margin: 0; padding: 0; border: 0; }

.cr-pick {
  position: relative; display: grid; grid-template-columns: 18px minmax(0, 1fr) auto minmax(136px, auto);
  align-items: center; column-gap: 12px;
}

.cr-pick .status-badge { justify-self: end; }

.cr-pick__radio { position: absolute; width: 1px; height: 1px; margin: 0; padding: 0; opacity: 0; pointer-events: none; }

.cr-pick__mark {
  width: 18px; height: 18px; box-sizing: border-box; display: grid; place-items: center;
  border: 2px solid rgba(var(--hair), .32); border-radius: var(--radius-pill); background: var(--surface);
  transition: border-color .15s ease, box-shadow .15s ease;
}

.cr-pick__mark::after {
  content: ""; width: 8px; height: 8px; border-radius: var(--radius-pill); background: var(--accent);
  transform: scale(0); transition: transform .15s ease;
}

.cr-pick__radio:checked + .cr-pick__mark { border-color: var(--accent); }

.cr-pick__radio:checked + .cr-pick__mark::after { transform: scale(1); }

.cr-pick__radio:focus-visible + .cr-pick__mark { box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .35); }

.cr-pick:has(.cr-pick__radio:focus-visible) { box-shadow: inset 0 0 0 2px rgba(var(--accent-rgb), .55); }

.cr-pick__total { font-size: 14.5px; font-weight: 750; letter-spacing: -.005em; font-variant-numeric: tabular-nums; white-space: nowrap; }

.cr-option[data-expanded="true"] > .cr-pick { box-shadow: inset 3px 0 0 var(--accent); }

.cr-option[data-expanded="true"] > .cr-pick:has(.cr-pick__radio:focus-visible) {
  box-shadow: inset 3px 0 0 var(--accent), inset 0 0 0 2px rgba(var(--accent-rgb), .55);
}

.cr-property__foot { padding: 14px 18px 16px; border-top: 1px solid var(--glass-border); }

.cr-property__foot > :first-child { margin-top: 0; }

.cr-property__foot > .cr-confirm, .cr-property__foot > .cr-outcome { margin-top: 12px; }

.cr-property__foot > .cr-confirm:first-child, .cr-property__foot > .cr-outcome:first-child { margin-top: 0; }

.cr-property__actions { margin-top: 12px; }

.cr-property__head .cr-property__address:focus { outline: none; }

.cr-option__body { padding: 4px 18px 18px; }

.cr-option__head { margin: 0; padding: 13px 18px 0; font-size: 14.5px; font-weight: 700; }

.cr-lines-wrap { margin-top: 6px; }

.cr-lines { width: 100%; border-collapse: collapse; font-size: 13.5px; }

.cr-lines th {
  padding: 8px 0; text-align: left; font-size: 11px; font-weight: 700; letter-spacing: .05em;
  text-transform: uppercase; color: var(--ink-3); border-bottom: 1px solid rgba(var(--hair), .08);
}

.cr-lines td { padding: 10px 0; vertical-align: top; border-bottom: 1px solid rgba(var(--hair), .05); }

.cr-lines th + th, .cr-lines td + td { padding-left: 16px; }

.cr-lines th.cr-num, .cr-num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }

.cr-lines th.cr-num { width: 128px; padding-left: 32px; }

.cr-lines__service { font-weight: 600; overflow-wrap: anywhere; }

.cr-lines-empty { padding-bottom: 10px; border-bottom: 1px solid rgba(var(--hair), .05); }

.cr-lines-empty:has(+ .cr-total),
.cr-lines-wrap:has(+ .cr-total) tbody tr:last-child,
.cr-lines-wrap:has(+ .cr-total) tbody tr:last-child td { border-bottom-color: transparent; }

.cr-total {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
  margin-top: 2px; padding-top: 12px; border-top: 1.5px solid rgba(var(--hair), .1);
}

.cr-total__label { font-size: 13px; font-weight: 700; color: var(--ink-2); }

.cr-total__value { font-size: 18px; font-weight: 800; letter-spacing: -.01em; font-variant-numeric: tabular-nums; }

.cr-total__value.cr-muted { font-size: 13.5px; font-weight: 500; letter-spacing: normal; }

.cr-breakdown { margin: 0; padding: 8px 0 6px; }

.cr-breakdown__row { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 3px 0; font-size: 13px; }

.cr-breakdown__label { color: var(--ink-2); }

.cr-breakdown__value { margin: 0; font-weight: 600; color: var(--ink); font-variant-numeric: tabular-nums; }

.cr-note { margin: 12px 0 0; font-size: 13px; line-height: 1.55; color: var(--ink-2); }

.cr-note--pending { display: flex; align-items: center; gap: 9px; }

.cr-note--pending::before {
  content: ""; width: 14px; height: 14px; flex: none; border-radius: var(--radius-pill);
  border: 2px solid rgba(var(--accent-rgb), .2); border-top-color: var(--accent);
  animation: cr-spin .8s linear infinite;
}

@keyframes cr-spin { to { transform: rotate(360deg); } }

.cr-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 16px; }

.cr-actions .btn { white-space: normal; text-align: center; }

.cr-confirm {
  margin-top: 16px; padding: 14px 16px; border-radius: 16px;
  background: rgba(var(--accent-rgb), .06); border: 1px solid rgba(var(--accent-rgb), .18);
}

.cr-confirm--decline { background: var(--danger-bg); border-color: transparent; }

.cr-confirm--changes { background: rgba(var(--glass), .5); border-color: var(--glass-border); }

.cr-confirm__title { margin: 0; font-size: 14.5px; font-weight: 750; line-height: 1.4; }

.cr-confirm__body { margin: 4px 0 0; font-size: 13.5px; line-height: 1.5; color: var(--ink-2); }

.cr-confirm .cr-actions, .cr-approve .cr-actions { margin-top: 12px; }

.cr-approve[role="group"] { border-color: rgba(var(--accent-rgb), .4); }

.cr-approve .cr-note { margin-top: 0; }

.cr-outcome {
  display: flex; align-items: flex-start; gap: 11px; flex-wrap: wrap;
  margin-top: 14px; padding: 12px 14px; border-radius: 14px; background: var(--danger-bg);
}

.cr-outcome__icon {
  width: 22px; height: 22px; flex: none; margin-top: 1px; border-radius: var(--radius-pill);
  display: grid; place-items: center; font-size: 12px; font-weight: 800;
  color: var(--danger); background: var(--surface);
}

.cr-outcome__body { flex: 1 1 220px; min-width: 0; }

.cr-outcome__title { margin: 0; font-size: 13.5px; font-weight: 700; line-height: 1.4; }

.cr-outcome__text { margin: 2px 0 0; font-size: 13px; line-height: 1.5; color: var(--ink-2); overflow-wrap: anywhere; }

.cr-outcome .btn { flex: none; align-self: center; }

.cr-option__body > .cr-notice { margin-top: 14px; }

.cr-approved__list { list-style: none; margin: 0; padding: 0; }

.cr-approved__item {
  display: flex; flex-direction: column; gap: 12px;
  padding: 11px 0; border-top: 1px solid rgba(var(--hair), .06);
}

.cr-approved__row { display: flex; align-items: center; justify-content: space-between; gap: 14px; }

.cr-approved__item:first-child { padding-top: 0; border-top: 0; }

.cr-approved__identity { display: flex; flex-direction: column; gap: 2px; min-width: 0; }

.cr-approved__address { font-size: 14px; font-weight: 650; overflow-wrap: anywhere; }

.cr-approved__option { font-size: 12.5px; color: var(--ink-3); }

.cr-approved__total { flex: none; font-size: 14.5px; font-weight: 800; font-variant-numeric: tabular-nums; }

.cr-approved__total.cr-muted { font-size: 13.5px; font-weight: 500; }

.cr-plan {
  display: flex; flex-direction: column; gap: 10px; padding: 14px;
  border-radius: var(--radius-md); background: var(--surface-2); border: 1px solid rgba(var(--hair), .08);
}

.cr-plan__title { margin: 0; font-size: 12px; font-weight: 700; letter-spacing: .02em; color: var(--ink-2); }

.cr-plan__placeholder { height: 240px; border-radius: var(--radius-sm); }

.cr-plan .cr-note { margin-top: 0; }

.cr-plan__area {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 2px 12px;
  margin: 0; font-size: 13px; color: var(--ink-2);
}

.cr-plan__area-value { font-size: 14.5px; font-weight: 800; color: var(--ink); font-variant-numeric: tabular-nums; }

.cr-plan__legend {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 6px 18px;
  margin: 0; padding: 0; list-style: none;
}

.cr-plan__element { display: flex; align-items: center; gap: 8px; min-width: 0; font-size: 13px; line-height: 1.45; }

.cr-plan__swatch { flex: none; width: 14px; height: 14px; border-radius: 4px; background: var(--accent); }

.cr-plan__swatch[data-kind="line"] { height: 4px; border-radius: var(--radius-pill); }

.cr-plan__swatch[data-kind="point"] { border-radius: var(--radius-pill); }

.cr-plan__swatch[data-tone="2"] { background: var(--warn); }

.cr-plan__swatch[data-tone="3"] { background: var(--ok); }

.cr-plan__swatch[data-tone="4"] { background: var(--danger); }

.cr-plan__swatch[data-tone="5"] { background: var(--accent-3); }

.cr-plan__name { min-width: 0; overflow-wrap: anywhere; }

.cr-plan__size { flex: none; margin-left: auto; color: var(--ink-3); font-variant-numeric: tabular-nums; }

.cr-plan__note { margin: 0; font-size: 12px; line-height: 1.5; color: var(--ink-3); }

.cr-plan[data-state="unavailable"] .cr-plan__note { font-size: 13px; color: var(--ink-2); }

.cr-map { display: none; }

.cr-map[data-state="ready"],
.cr-map[data-state="stale"],
.cr-map[data-state="missing"],
.cr-map[data-state="loading"] { display: block; }

.cr-map__canvas {
  height: 220px; overflow: hidden; isolation: isolate;
  border-radius: var(--radius-sm); border: 1px solid rgba(var(--hair), .1); background: var(--surface-2);
  transition: opacity .16s;
}

.cr-map[data-map="plan"] .cr-map__canvas { height: 280px; }

.cr-map[data-state="loading"] .cr-map__canvas {
  background: linear-gradient(90deg, rgba(var(--hair), .06) 25%, rgba(var(--hair), .12) 37%, rgba(var(--hair), .06) 63%);
  background-size: 720px 100%; animation: shimmer 1.4s ease-in-out infinite;
}

.cr-map[data-state="stale"] .cr-map__canvas { opacity: .55; }

.cr-map[data-state="missing"] .cr-map__canvas { display: none; }

.cr-map__note { margin: 0; font-size: 12px; line-height: 1.5; color: var(--ink-2); }

.cr-map__note:empty { display: none; }

.cr-address { position: relative; }

.cr-suggest {
  position: absolute; top: 100%; left: 0; right: 0; z-index: 20;
  margin: 4px 0 0; padding: 6px; list-style: none;
  background: var(--surface); border: 1px solid rgba(var(--hair), .1);
  border-radius: var(--radius-md); box-shadow: var(--shadow-float);
}

.cr-suggest[hidden] { display: none; }

.cr-suggest__option {
  padding: 9px 11px; border-radius: calc(var(--radius-md) - 4px);
  font-size: 14px; color: var(--ink); cursor: pointer;
}

.cr-suggest__option:hover { background: rgba(var(--accent-rgb), .07); }

.cr-suggest__option[aria-selected="true"] {
  background: rgba(var(--accent-rgb), .14);
  box-shadow: inset 0 0 0 1px rgba(var(--accent-rgb), .3);
}

.cr-reuse { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; }

.cr-reuse__label { margin: 0; font-size: 12px; color: var(--ink-3); }

.cr-reuse__chips { display: flex; flex-wrap: wrap; gap: 6px; min-width: 0; }

.btn.cr-chip {
  max-width: 100%; padding: 6px 12px; font-size: 12.5px; font-weight: 600;
  overflow: hidden; text-overflow: ellipsis;
  color: var(--ink-2); background: var(--surface-2); border: 1px solid rgba(var(--hair), .14);
}

.btn.cr-chip:hover { border-color: rgba(var(--accent-rgb), .45); color: var(--ink); }

.btn.cr-chip[data-state="chosen"] {
  color: var(--accent); background: rgba(var(--accent-rgb), .1); border-color: rgba(var(--accent-rgb), .45);
}

.cr-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px 16px; }

.cr-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }

.cr-field[data-kind="address"],
.cr-field[data-kind="boolean"],
.cr-field[data-kind="textarea"],
.cr-field[data-kind="radio"] { grid-column: 1 / -1; }

.cr-field__label {
  display: flex; align-items: baseline; gap: 4px;
  font-size: 12px; font-weight: 700; letter-spacing: .02em; color: var(--ink-2);
}

.cr-req { margin-left: 3px; font-weight: 800; color: var(--danger); }

.cr-field__error { margin: 0; font-size: 12px; line-height: 1.45; color: var(--danger); }

.cr-field__error:empty { display: none; }

.cr-field__hint { margin: 0; font-size: 12px; line-height: 1.5; color: var(--ink-3); }

.cr-input {
  width: 100%; box-sizing: border-box; padding: 11px 13px; border-radius: var(--radius-md);
  font: inherit; font-size: 14px; color: var(--ink);
  background: var(--surface-2); border: 1px solid rgba(var(--hair), .14);
  outline: none; transition: border-color .16s, box-shadow .16s;
}

.cr-input::placeholder { color: var(--ink-3); }

.cr-input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .14); }

.cr-input:disabled { opacity: .6; cursor: not-allowed; }

.cr-input--area { min-height: 96px; resize: vertical; line-height: 1.55; }

.cr-select {
  appearance: none; cursor: pointer; padding-right: 38px;
  background-image: linear-gradient(45deg, transparent 50%, var(--ink-3) 50%), linear-gradient(135deg, var(--ink-3) 50%, transparent 50%);
  background-position: calc(100% - 19px) calc(50% + 2px), calc(100% - 14px) calc(50% + 2px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.cr-field[data-state="invalid"] .cr-input { border-color: var(--danger); box-shadow: 0 0 0 3px var(--danger-bg); }

.cr-choices { display: flex; flex-direction: column; gap: 9px; }

.cr-choice { position: relative; display: flex; align-items: flex-start; gap: 10px; font-size: 14px; line-height: 1.45; color: var(--ink); cursor: pointer; }

.cr-choice__input { position: absolute; width: 1px; height: 1px; margin: 0; opacity: 0; }

.cr-choice__label { flex: 1; }

.cr-check {
  width: 20px; height: 20px; flex-shrink: 0; margin-top: 1px; border-radius: 7px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800; color: var(--surface);
  background: var(--surface-2); border: 1.5px solid rgba(var(--hair), .28);
  transition: border-color .16s, background .16s;
}

.cr-choice__input:checked + .cr-check { background: var(--accent); border-color: var(--accent); }

.cr-choice__input:checked + .cr-check::after { content: "✓"; }

.cr-radio {
  width: 22px; height: 22px; flex-shrink: 0; border-radius: var(--radius-pill); display: grid; place-items: center;
  background: var(--surface-2); border: 2px solid rgba(var(--hair), .28);
}

.cr-choice__input:checked + .cr-radio { background: var(--accent); border-color: var(--accent); }

.cr-choice__input:checked + .cr-radio::after { content: ""; width: 8px; height: 8px; border-radius: var(--radius-pill); background: var(--surface); }

.cr-choice__input:focus-visible + .cr-check,
.cr-choice__input:focus-visible + .cr-radio { box-shadow: 0 0 0 3px rgba(var(--accent-rgb), .18); }

.cr-field[data-state="invalid"] .cr-check,
.cr-field[data-state="invalid"] .cr-radio { border-color: var(--danger); }

.cr-form .cr-notice, .cr-form .cr-outcome { margin-top: 18px; }

.cr-form-actions { display: flex; justify-content: flex-end; margin-top: 22px; }

.cr-parties { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; align-items: start; }

.cr-party__logo { display: block; max-width: min(220px, 70%); max-height: 52px; width: auto; height: auto; margin: 0 0 12px; object-fit: contain; }

.cr-party__logo[hidden] { display: none; }

:root[data-mode="dark"] .cr-party__logo {
  max-width: min(240px, calc(70% + 20px)); max-height: 64px;
  padding: 6px 10px; border-radius: 10px; background: var(--bg-3);
}

.cr-facts { margin: 0; }

.cr-facts__row {
  display: grid; grid-template-columns: minmax(96px, 34%) minmax(0, 1fr); gap: 12px;
  padding: 9px 0; border-top: 1px solid rgba(var(--hair), .06);
}

.cr-facts__row:first-child { padding-top: 0; border-top: 0; }

.cr-facts__label { font-size: 12.5px; color: var(--ink-3); }

.cr-facts__value { margin: 0; font-size: 13.5px; font-weight: 600; overflow-wrap: anywhere; }

.cr-terms__heading { margin: 18px 0 6px; font-size: 14.5px; font-weight: 750; }

.cr-terms .cr-section-title + .cr-terms__heading { margin-top: 4px; }

.cr-terms__paragraph { margin: 0 0 10px; font-size: 13.5px; line-height: 1.65; color: var(--ink-2); white-space: pre-line; }

.cr-terms__list { margin: 0 0 10px; padding-left: 20px; font-size: 13.5px; line-height: 1.65; color: var(--ink-2); }

.cr-terms__list li + li { margin-top: 4px; }

.cr-terms__clauses { list-style: none; margin: 0 0 10px; padding: 0; font-size: 13.5px; line-height: 1.65; color: var(--ink-2); }

.cr-terms__clause { display: grid; grid-template-columns: minmax(2em, max-content) minmax(0, 1fr); column-gap: .55em; }

.cr-terms__clause + .cr-terms__clause { margin-top: 4px; }

.cr-terms__clause + .cr-terms__clause[data-depth="1"] { margin-top: 12px; }

.cr-terms__clause[data-depth="2"] { padding-left: 2.55em; }

.cr-terms__clause[data-depth="3"] { padding-left: 5.1em; }

.cr-terms__number { font-weight: 700; color: var(--ink); font-variant-numeric: tabular-nums; white-space: nowrap; }

.cr-terms__clause-text { min-width: 0; white-space: pre-line; overflow-wrap: anywhere; }

.cr-contact {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 24px;
  padding: 14px 18px; border-radius: 16px;
  background: rgba(var(--glass), .4); border: 1px solid var(--glass-border);
}

.cr-contact__identity { min-width: 0; }

.cr-contact__title { margin: 0; font-size: 14px; font-weight: 750; letter-spacing: -.005em; }

.cr-contact__name { margin: 2px 0 0; font-size: 12.5px; color: var(--ink-3); overflow-wrap: anywhere; }

.cr-contact__list { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px 24px; }

.cr-contact__item { display: flex; align-items: baseline; gap: 8px; min-width: 0; font-size: 13.5px; }

.cr-contact__label { font-size: 12px; color: var(--ink-3); }

.cr-contact__link, .cr-contact__value { padding: 6px 0; font-weight: 650; color: var(--ink); overflow-wrap: anywhere; }

.cr-contact__link {
  text-decoration: underline; text-decoration-color: rgba(var(--accent-rgb), .55);
  text-decoration-thickness: 1.5px; text-underline-offset: 3px;
}

.cr-contact__link:hover { text-decoration-color: var(--accent); }

.cr-skeleton { display: flex; flex-direction: column; gap: 16px; }

.cr-skeleton__bar { display: block; border-radius: 8px; }

.cr-skeleton__eyebrow { width: 96px; height: 11px; }

.cr-skeleton__title { width: min(420px, 70%); height: 30px; border-radius: 10px; }

.cr-skeleton__sub { width: min(560px, 90%); height: 14px; }

.cr-skeleton__tile { height: 66px; border-radius: var(--radius-md); }

.cr-skeleton__pin { width: 26px; height: 26px; flex: none; border-radius: var(--radius-pill); }

.cr-skeleton__address { width: 55%; height: 18px; margin-top: 4px; }

.cr-skeleton__row {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 14px 18px; border-top: 1px solid var(--glass-border);
}

.cr-skeleton__label { width: 30%; height: 13px; }

.cr-skeleton__chip { width: 92px; height: 22px; border-radius: var(--radius-pill); }

@media (max-width: 880px) {
  .cr-summary { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .cr-parties { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 560px) {
  .cr-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cr-summary__item[data-kind="properties"],
  .cr-skeleton .cr-summary > .cr-skeleton__tile:first-child { grid-column: 1 / -1; }
  .cr-fields { grid-template-columns: minmax(0, 1fr); }
  .cr-link__copy { padding: 9px 16px; font-size: 13px; }
  .cr-contact { flex-direction: column; align-items: flex-start; gap: 4px; padding: 14px 14px 4px; }
  .cr-contact__list { flex-direction: column; gap: 0; }
  .cr-contact__link, .cr-contact__value { padding: 12px 0; }
  .cr-property__head { flex-wrap: wrap; padding: 14px 14px 12px; gap: 8px 10px; }
  .cr-property__identity { flex-basis: calc(100% - 40px); }
  .cr-property__head .status-badge { margin: 0 0 0 40px; }
  .cr-option__toggle { padding: 12px 14px; }
  .cr-pick { grid-template-columns: 18px minmax(0, 1fr) auto; row-gap: 6px; }
  .cr-pick .status-badge { grid-column: 2 / -1; justify-self: start; }
  .cr-property__foot { padding: 12px 14px 14px; }
  .cr-option__head { padding: 12px 14px 0; }
  .cr-option__body { padding: 2px 14px 16px; }
  .cr-actions { flex-direction: column; align-items: stretch; }
  .cr-actions .btn, .cr-form-actions .btn { width: 100%; }
  .cr-facts__row { grid-template-columns: minmax(0, 1fr); gap: 2px; }
  .cr-approved__row { align-items: flex-start; }
  .cr-plan { padding: 12px; }
  .cr-map__canvas, .cr-plan__placeholder { height: 200px; }
  .cr-map[data-map="plan"] .cr-map__canvas { height: 240px; }
  .cr-plan__legend { grid-template-columns: minmax(0, 1fr); }
  .cr-lines thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
  .cr-lines, .cr-lines tbody, .cr-lines tr, .cr-lines td { display: block; width: 100%; }
  .cr-lines tr { padding: 10px 0; border-bottom: 1px solid rgba(var(--hair), .06); }
  .cr-lines td, .cr-lines td + td { padding: 2px 0; border: 0; }
  .cr-lines td.cr-num { display: flex; justify-content: space-between; gap: 12px; font-size: 13px; color: var(--ink-2); }
  .cr-lines td.cr-num::before { content: attr(data-label); font-size: 12px; color: var(--ink-3); }
  .cr-lines__service { margin-bottom: 4px; font-size: 14px; }
  .cr-terms__clause[data-depth="2"] { padding-left: 1.2em; }
  .cr-terms__clause[data-depth="3"] { padding-left: 2.4em; }
}

@media (prefers-reduced-motion: reduce) {
  .cr-pick__mark, .cr-pick__mark::after, .cr-input, .cr-check, .cr-page[aria-busy="true"] .cr-property { transition: none; }
  .cr-note--pending::before, .cr-state[data-checking="active"] .cr-state__glyph::after, .cr-notice__icon--busy::after { animation: none; }
  .cr-map[data-state="loading"] .cr-map__canvas, .cr-map__canvas { animation: none; transition: none; }
}

html, body { min-height: 100%; }
body { margin: 0; background: var(--app-bg); color: var(--ink); font-family: var(--font); }
